<?php namespace App\Http\Controllers\Api\V1; use Illuminate\Http\Request; use App\Models\{FeeType,StudentFee,FeePayment}; class FeeController extends Controller {protected function admin(Request $r){$this->authorizeRole($r,['super_admin','admin']);}public function types(Request $r){$this->authorizeRole($r,['super_admin','admin']);return $this->ok(FeeType::where('school_id',$r->user()->school_id)->paginate(50));}public function createType(Request $r){$this->admin($r);$d=$r->validate(['name'=>'required|string','description'=>'nullable|string']);$d['school_id']=$r->user()->school_id;return $this->ok(FeeType::create($d),'Fee type created',201);}public function updateType(Request $r,$id){$this->admin($r);$x=FeeType::where('school_id',$r->user()->school_id)->findOrFail($id);$x->update($r->all());return $this->ok($x,'Fee type updated');}public function deleteType(Request $r,$id){$this->admin($r);FeeType::where('school_id',$r->user()->school_id)->findOrFail($id)->delete();return $this->ok(null,'Fee type deleted');}public function studentFees(Request $r){$this->admin($r);$q=StudentFee::where('school_id',$r->user()->school_id)->when($r->student_id,fn($q)=>$q->where('student_id',$r->student_id))->when($r->status,fn($q)=>$q->where('status',$r->status))->when($r->month,fn($q)=>$q->where('month',$r->month));return $this->ok($q->paginate(50));}public function assign(Request $r){$this->admin($r);$d=$r->validate(['student_id'=>'required|integer','fee_type_id'=>'required|integer','amount'=>'required|numeric|min:0','month'=>'nullable|string','due_date'=>'nullable|date']);$d['school_id']=$r->user()->school_id;$d['status']='unpaid';return $this->ok(StudentFee::create($d),'Fee assigned',201);}public function payment(Request $r){$this->admin($r);$d=$r->validate(['student_fee_id'=>'required|integer','amount'=>'required|numeric|min:0','payment_method'=>'required|string','payment_date'=>'nullable|date']);$fee=StudentFee::where('school_id',$r->user()->school_id)->findOrFail($d['student_fee_id']);$d['school_id']=$r->user()->school_id;$d['receipt_no']='KCS-'.date('YmdHis').'-'.random_int(100,999);$p=FeePayment::create($d);$paid=FeePayment::where('student_fee_id',$fee->id)->sum('amount');$fee->status=$paid >= $fee->amount?'paid':($paid>0?'partial':'unpaid');$fee->save();return $this->ok(['payment'=>$p,'fee'=>$fee],'Payment recorded',201);}}
